from collections import deque


def min_steps_through_walls(grid, k):
    if not grid or not grid[0]:
        return -1
    m, n = len(grid), len(grid[0])
    if grid[0][0] > k:
        return -1
    if m == 1 and n == 1:
        return 0
    best = [[-1] * n for _ in range(m)]
    start_rem = k - grid[0][0]
    best[0][0] = start_rem
    q = deque([(0, 0, start_rem)])
    steps = 0
    while q:
        steps += 1
        for _ in range(len(q)):
            r, c, rem = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    nrem = rem - grid[nr][nc]
                    if nrem < 0:
                        continue
                    if nr == m - 1 and nc == n - 1:
                        return steps
                    if nrem > best[nr][nc]:
                        best[nr][nc] = nrem
                        q.append((nr, nc, nrem))
    return -1
